    let offset = 0;

    function readInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let res = 0;
        while (offset < buffer.length && buffer[offset] > 32) {
            res = res * 10 + (buffer[offset] - 48);
            offset++;
        }
        return res;
    }

    const N = readInt();
    if (N === null) return;
    const M = readInt();

    const T = new Int32Array(N);
    for (let i = 0; i < N; i++) {
        T[i] = readInt();
    }

    const F = new Int32Array(M);
    for (let i = 0; i < M; i++) {
        F[i] = readInt();
    }

    // Ordena os tempos dos carros em ordem decrescente
    T.sort();
    // T está em ordem crescente, vamos iterar de trás para frente ou inverter
    // Invertendo para ter ordem decrescente:
    let l = 0, r = N - 1;
    while (l < r) {
        let tmp = T[l];
        T[l] = T[r];
        T[r] = tmp;
        l++;
        r--;
    }

    // Os primeiros M carros receberão coeficiente 0 (se N <= M, todos esperam 0)
    // Precisamos de coeficientes para os carros restantes a partir do índice M até N-1.
    const needed = N - M;
    if (needed <= 0) {
        console.log("0");
        return;
    }

    // Min-Heap eficiente usando Flat Arrays
    // Precisamos apenas dos menores 'needed' valores gerados por p * F[j], para p >= 1.
    // Inicialmente inserimos (1 * F[j], F[j]) para cada mecânico j.
    // Para otimizar o tamanho da heap, se M > needed, podemos pegar apenas os 'needed' menores F[j].
    F.sort();
    const heapSizeLimit = Math.min(M, needed);

    const heapVal = new Float64Array(heapSizeLimit + 1);
    const heapStep = new Int32Array(heapSizeLimit + 1);
    let heapSize = 0;

    function push(val, step) {
        let i = ++heapSize;
        while (i > 1) {
            let p = i >> 1;
            if (heapVal[p] <= val) break;
            heapVal[i] = heapVal[p];
            heapStep[i] = heapStep[p];
            i = p;
        }
        heapVal[i] = val;
        heapStep[i] = step;
    }

    function pop() {
        const topVal = heapVal[1];
        const topStep = heapStep[1];

        const lastVal = heapVal[heapSize];
        const lastStep = heapStep[heapSize];
        heapSize--;

        if (heapSize > 0) {
            let i = 1;
            while ((i << 1) <= heapSize) {
                let left = i << 1;
                let right = left + 1;
                let best = left;
                if (right <= heapSize && heapVal[right] < heapVal[left]) {
                    best = right;
                }
                if (lastVal <= heapVal[best]) break;
                heapVal[i] = heapVal[best];
                heapStep[i] = heapStep[best];
                i = best;
            }
            heapVal[i] = lastVal;
            heapStep[i] = lastStep;
        }

        return { val: topVal, step: topStep };
    }

    for (let i = 0; i < heapSizeLimit; i++) {
        push(F[i], F[i]);
    }

    let totalWait = 0n;

    // Os carros de 0 até M - 1 têm coeficiente 0.
    // Os carros de M até N - 1 serão associados aos menores coeficientes da heap.
    for (let i = M; i < N; i++) {
        const minElem = pop();
        const c = minElem.val;
        const step = minElem.step;

        totalWait += BigInt(T[i]) * BigInt(c);

        push(c + step, step);
    }

    console.log(totalWait.toString());
}

solve();
